// This file is generated by AI.

// 状态栏: LSP 状态、(配音工作台打开时的) GSOV 状态、诊断数、光标位置、字数与行数。
//
// GSOV 状态**只在配音工作台打开时出现**: 未启用配音功能时, 状态栏保持干净;
// 一旦工作台打开, 无论当前是否停在场景卡上, 都能在底部看到服务是否就绪。
//
// 它和 LSP 那一项是同一种东西: **名称 + 一句话状态**, 不承载计数。待处理的配音任务
// 数属于"工作台里正在发生什么", 由工作台选项卡的角标负责 —— 状态栏里再放一个
// `队列 3` 只会让人以为那是常驻指标。
//
// 诊断数是**整个项目**的合计 (含未打开的场景), 不是当前这张卡的: 它就是诊断列表的入口,
// 而那个列表列的是全项目的问题。级别上只统计错误与警告 —— 信息级 (目前只有 WG001 的
// 格式建议) 数量最多且不代表"坏了", 计进去会让这个数字长期虚高。

import { useMemo } from 'react';

import { collectProjectDiagnostics } from '../diagnostics/model';
import { isVoiceWorkbenchOpen, useAppStore } from '../state/store';

const GSV_LABELS: Record<string, string> = {
  ready: '就绪',
  starting: '启动中…',
  stopping: '停止中…',
  error: '错误',
  stopped: '未启动',
};

export function StatusBar() {
  const lspStatus = useAppStore((s) => s.lspStatus);
  const lspError = useAppStore((s) => s.lspError);
  const lspActivity = useAppStore((s) => s.lspActivity);
  const cursor = useAppStore((s) => s.cursor);
  const diagnostics = useAppStore((s) => s.diagnostics);
  const projectPath = useAppStore((s) => s.projectPath);
  const diagnosticsOpen = useAppStore((s) => s.diagnosticsOpen);
  const setDiagnosticsOpen = useAppStore((s) => s.setDiagnosticsOpen);
  const novelStats = useAppStore((s) => s.novelStats);
  // 工作台是普通选项卡: 是否打开由选项卡序列推导
  const workbenchOpen = useAppStore((s) => isVoiceWorkbenchOpen(s.tabs));
  const voiceStatus = useAppStore((s) => s.voiceStatus);
  const voiceStatusDetail = useAppStore((s) => s.voiceStatusDetail);

  // 活动选项卡决定展示哪一类统计信息
  const active = useAppStore((s) => s.tabs.find((item) => item.id === s.activeTabId) ?? null);
  const activeDoc = useAppStore((s) =>
    active?.kind === 'scene' ? (s.documents.find((doc) => doc.path === active.path) ?? null) : null
  );

  const projectDiagnostics = useMemo(() => {
    const { files } = collectProjectDiagnostics(diagnostics, projectPath);
    let problems = 0;
    let errors = 0;
    for (const file of files) {
      for (const entry of file.entries) {
        if (entry.severity === 1) {
          errors += 1;
          problems += 1;
        } else if (entry.severity === 2) {
          problems += 1;
        }
      }
    }
    return { problems, errors };
  }, [diagnostics, projectPath]);

  const isNovel = active?.kind === 'novel';
  const charCount = isNovel ? (novelStats?.chars ?? 0) : (activeDoc?.content.length ?? 0);
  const lineCount = isNovel ? (novelStats?.lines ?? 0) : activeDoc ? activeDoc.content.split('\n').length : 0;

  return (
    <div className="status-bar" title={lspActivity ?? lspError ?? voiceStatusDetail ?? undefined}>
      {/*
        "就绪"说的是连接, 不是"答得上来": 语言服务处理大批文件变更时会长时间不答复任何
        请求 (issue #25)。这时照旧写"就绪"等于骗人 —— 有请求超时未答就改说"响应缓慢",
        答复一到自动恢复 (见 `lsp/client.ts` 的忙闲判断)。
      */}
      <span className={`lsp-status ${lspActivity ? 'lsp-syncing' : `lsp-${lspStatus}`}`}>
        LSP:{' '}
        {lspActivity
          ? '响应缓慢'
          : lspStatus === 'ready'
            ? '就绪'
            : lspStatus === 'connecting'
              ? '连接中'
              : lspStatus === 'error'
                ? '错误'
                : '未连接'}
      </span>

      {/*
        「停止中…」要在工作台已经关掉之后继续显示一会儿: 关闭工作台会顺手停掉 GSOV,
        而进程收尾需要时间 —— 这一项立刻消失的话, 用户看到的是"点了关闭, 服务还在,
        然后突然没了", 不知道中间发生了什么。停完 (stopped) 它自然收起。
      */}
      {(workbenchOpen || voiceStatus === 'stopping') && (
        <span className={`status-voice status-voice-${voiceStatus}`}>
          GSOV: {GSV_LABELS[voiceStatus] ?? voiceStatus}
        </span>
      )}

      <button
        type="button"
        className={`status-diag${diagnosticsOpen ? ' open' : ''}`}
        title="查看整个项目的诊断（不含信息级与提示）"
        aria-expanded={diagnosticsOpen}
        onClick={() => setDiagnosticsOpen(!diagnosticsOpen)}
      >
        诊断: {projectDiagnostics.problems}
        {projectDiagnostics.errors > 0 ? ` (错误 ${projectDiagnostics.errors})` : ''}
      </button>
      <span className="status-spacer" />
      {cursor ? (
        <span className="status-cursor">
          行 {cursor.line}, 列 {cursor.column}
        </span>
      ) : null}
      <span className="status-chars">字符 {charCount}</span>
      <span className="status-lines">行数 {lineCount}</span>
    </div>
  );
}
